-- Existing production-shaped tables and privileges, synthetic data only.
create table public.customer_bindings (
 phone text primary key, agent_name text not null, created_at timestamptz default now(),
 protected_until timestamptz, last_activity_at timestamptz, last_activity_type text,
 last_purchase_at timestamptz, last_order_id text, previous_agent_name text,
 transferred_at timestamptz, updated_at timestamptz not null default now()
);
create table public.customer_binding_events (
 id bigint generated by default as identity primary key, phone text not null,
 previous_agent_name text, agent_name text not null, event_type text not null,
 order_id text, occurred_at timestamptz not null default now(), protected_until timestamptz,
 metadata jsonb not null default '{}'
);
create role binding_operations nologin;
grant usage on schema public to anon,authenticated,binding_operations;
grant select,insert,update,delete on public.customer_bindings,public.customer_binding_events to anon,authenticated,binding_operations;
grant usage on sequence public.customer_binding_events_id_seq to anon,authenticated,binding_operations;
-- Explicit column grants must also be removed from browser roles.
grant update(agent_name),insert(phone,agent_name) on public.customer_bindings to anon;
insert into public.customer_bindings(phone,agent_name,created_at,last_activity_type,previous_agent_name)
 values('05358123456','Historic owner','2020-01-01T00:00:00Z','legacy','Previous owner');
insert into public.customer_bindings(phone,agent_name) values('58123450','Other owner');
-- Supabase environments may have broad default service privileges; private
-- proof must explicitly narrow them, including TRUNCATE (which skips row guards).
alter default privileges grant all on tables to service_role;
